 function results(data,q){const seen=new Set();return (Array.isArray(data?.results)?data.results:[]).slice(0,20).map(r=>normalize(r,q.zip?q.value:null)).filter(r=>{if(!r)return false;const id=[r.label,r.latitude,r.longitude].join('|');if(seen.has(id))return false;seen.add(id);return true}).slice(0,10)}
