 function validForecast(f,r){const d=f?.daily,h=f?.hourly;if(!d||!h||!Number.isFinite(f.latitude)||!Number.isFinite(f.longitude)||Math.abs(f.latitude-r.latitude)>2||Math.abs(((f.longitude-r.longitude+540)%360)-180)>2)return false;const n=d.time?.length;if(!n||n>16||!d.time.every(x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x))||!['temperature_2m_max','temperature_2m_min','precipitation_sum','wind_speed_10m_max'].every(k=>Array.isArray(d[k])&&d[k].length===n&&d[k].every(v=>v===null||Number.isFinite(v))))return false;return Array.isArray(h.time)&&h.time.length<=400&&Array.isArray(h.cloud_cover)&&h.cloud_cover.length===h.time.length&&h.cloud_cover.every(v=>v===null||(Number.isFinite(v)&&v>=0&&v<=100))}
